package com.futurehouser.f76checker

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool

/** Short UI sound cues (generated by tools/gen_sounds.py). */
enum class Sound(val res: Int) {
    CHECK(R.raw.sfx_check),
    UNCHECK(R.raw.sfx_uncheck),
    CLICK(R.raw.sfx_click),
    NAV(R.raw.sfx_nav),
    BACK(R.raw.sfx_back),
    DRAWER(R.raw.sfx_drawer),
    LANG(R.raw.sfx_lang),
    COMPLETE(R.raw.sfx_complete),
    ALERT(R.raw.sfx_alert),
}

object Sfx {
    private var pool: SoundPool? = null
    private val ids = mutableMapOf<Sound, Int>()
    var enabled = true

    fun init(context: Context) {
        if (pool != null) return
        val p = SoundPool.Builder()
            .setMaxStreams(4)
            .setAudioAttributes(
                AudioAttributes.Builder()
                    .setUsage(AudioAttributes.USAGE_ASSISTANCE_SONIFICATION)
                    .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                    .build()
            ).build()
        Sound.entries.forEach { ids[it] = p.load(context.applicationContext, it.res, 1) }
        pool = p
    }

    fun play(sound: Sound) {
        if (!enabled) return
        val id = ids[sound] ?: return
        pool?.play(id, 0.8f, 0.8f, 1, 0, 1f)
    }
}
